    it("local interaction outer wire matches strict fixtures and the independent LEB128 oracle", async () => {
      const { readFileSync } = await import("node:fs");
      const { default: Ajv } = await Promise.resolve().then(() => __toESM(require_ajv(), 1));
      const oracleModule = "@webassemblyjs/leb128/lib/leb.js";
      const imported = await import(oracleModule);
      if (!imported || typeof imported !== "object")
        throw new Error("invalid LEB128 oracle module");
      const oracle = Reflect.get(imported, "default");
      if (!oracle || typeof oracle !== "object")
        throw new Error("invalid LEB128 oracle interface");
      const encodeUnsigned = Reflect.get(oracle, "encodeUIntBuffer");
      if (typeof encodeUnsigned !== "function")
        throw new Error("missing LEB128 oracle encoder");
      const fixture = JSON.parse(readFileSync(new URL("./🧫️fixtures/🏠️local-interaction/🧪️query/🔣️.json", import.meta.url), "utf8"));
      const schema = JSON.parse(readFileSync(new URL("./🧫️fixtures/🏠️local-interaction/🧬️schema.json", import.meta.url), "utf8"));
      const validate = new Ajv({ strict: true }).compile(schema);
      expect(validate(fixture)).toBe(true);
      expect(validate({ ...fixture, lateTokenAccepted: true })).toBe(false);
      expect(validate({ ...fixture, terminalBeforeClosed: true })).toBe(false);
      const read3 = { LocalInteractionQuery: { seq: 9, command: { kind: "read", requestId: "13" } } };
      const rejected = { LocalInteractionQuery: { reply: { kind: "rejected", requestId: "13", code: "busy" } } };
      const u64 = (value) => {
        const bytes = Buffer.alloc(8);
        bytes.writeBigUInt64LE(value);
        const encoded = encodeUnsigned(bytes);
        if (!(encoded instanceof Uint8Array))
          throw new Error("invalid LEB128 oracle bytes");
        return Array.from(encoded);
      };
      expect([...encodeAppCommand(read3)]).toEqual([29, ...u64(9n), ...u64(2n), 0, ...u64(13n)]);
      expect(Buffer.from(encodeAppCommand(read3)).toString("hex")).toBe(fixture.outerReadHex);
      expect(Buffer.from(encodeAppFrame(rejected)).toString("hex")).toBe(fixture.outerRejectedHex);
      const receipt = { Done: { in_reply_to: 2 } };
      expect([...encodeAppFrame(receipt)]).toEqual([0, ...u64(2n)]);
      expect(Buffer.from(encodeAppFrame(receipt)).toString("hex")).toBe(fixture.receiptHex);
      for (const row of fixture.sequenceCases) {
        if (row.result === null)
          continue;
        const sequence = row.result.sequence;
        expect([...encodeAppCommand({ ReadDocument: { seq: sequence } })]).toEqual([7, ...u64(BigInt(sequence))]);
        if (row.result.request !== null) {
          const inner = [0, ...u64(BigInt(row.result.request))];
          expect([...encodeAppCommand({ LocalInteractionQuery: { seq: sequence, command: { kind: "read", requestId: row.result.request } } })]).toEqual([29, ...u64(BigInt(sequence)), ...u64(BigInt(inner.length)), ...inner]);
        }
      }
      expect(decodeAppCommand(encodeAppCommand(read3))).toEqual(read3);
      expect(decodeAppFrame(encodeAppFrame(rejected))).toEqual(rejected);
      expect(() => decodeAppCommand(Uint8Array.from([...encodeAppCommand(read3), 0]))).toThrow();
      expect(() => decodeAppFrame(Uint8Array.from([...encodeAppFrame(rejected), 0]))).toThrow();
    });
    it("local interaction client fixture lifecycles preserve ACK ownership and ordinary replies", async () => {
      const { readFileSync } = await import("node:fs");
      const fixture = JSON.parse(readFileSync(new URL("./🧫️fixtures/🏠️local-interaction/🧪️query/🔣️.json", import.meta.url), "utf8"));
      for (const row of fixture.lifecycles) {
        const broadcast = createTurnOutcomeBroadcast();
        const sent = [];
        const handle = { enqueue: (_id, events) => {
          for (const command of events.map(decodeAppCommand)) {
            sent.push(command);
            if ("LocalInteractionQuery" in command && !(["disposal-before-read-receipt", "coalesced-query-and-ordinary-receipts"].includes(row.id) && command.LocalInteractionQuery.command.kind === "read"))
              broadcast.push({ instanceId: 7, frames: [encodeAppFrame({ Done: { in_reply_to: command.LocalInteractionQuery.seq } })] });
          }
        }, outcomes: broadcast.stream };
        const client = new AppChannelClient(handle, new AppChannelRequestSequence, 7, "fixture");
        const abort = new AbortController;
        let consume;
        const consumed = new Promise((resolve2) => {
          consume = resolve2;
        });
        let complete = false;
        let queryResult;
        let ordinary;
        let ordinaryComplete = false;
        const token2 = { requestId: "1", queryGeneration: "41", identity: { appInstanceId: 7, generation: "9007199254740993", revision: "11".repeat(32), documentRevision: "22".repeat(32), topologyRevision: "33".repeat(32) }, ordinal: "0" };
        const push = (reply) => broadcast.push({ instanceId: 7, frames: [encodeAppFrame({ LocalInteractionQuery: { reply } })] });
        const flush = async () => {
          for (let index = 0;index < 12; index += 1)
            await Promise.resolve();
        };
        for (const event of row.events) {
          if (event === "read")
            queryResult = client.readLocalInteractionPages(() => {
              if (row.id === "synchronous-consumer-failure")
                throw new Error("synchronous consumer fixture");
              if (row.id === "consumer-failure")
                return Promise.reject(new Error("consumer fixture"));
              return consumed;
            }, abort.signal).then((identity) => {
              complete = true;
              return identity;
            }, (error) => {
              complete = true;
              return error;
            });
          else if (event === "ordinary")
            ordinary = client.readDocument().then((frames) => {
              ordinaryComplete = true;
              return frames;
            });
          else if (event === "started")
            push({ kind: "started", token: token2 });
          else if (event === "abort")
            abort.abort();
          else if (event === "dispose")
            client.dispose();
          else if (event === "malformed")
            broadcast.push({ instanceId: 7, frames: [Uint8Array.from(Buffer.from(fixture.malformedFrameHex, "hex"))] });
          else if (event === "readReceipt")
            broadcast.push({ instanceId: 7, frames: [encodeAppFrame({ Done: { in_reply_to: 1 } })] });
          else if (event === "wrongReceipt" || event === "duplicateReadReceipt") {
            broadcast.push({ instanceId: 7, frames: [encodeAppFrame({ Done: { in_reply_to: event === "wrongReceipt" ? 999 : 1 } })] });
            await flush();
            expect(ordinaryComplete).toBe(false);
          } else if (event === "ordinaryDone") {
            broadcast.push({ instanceId: 7, frames: [encodeAppFrame({ Done: { in_reply_to: 3 } })] });
            expect(await ordinary).toEqual([{ Done: { in_reply_to: 3 } }]);
          } else if (event === "ordinaryEmpty") {
            broadcast.push({ instanceId: 7, frames: [] });
            await flush();
            expect(ordinaryComplete).toBe(false);
          } else if (event === "mixedReceipts") {
            broadcast.push({ instanceId: 7, frames: [encodeAppFrame({ Done: { in_reply_to: 1 } }), encodeAppFrame({ Done: { in_reply_to: 3 } })] });
            await flush();
            expect(ordinaryComplete).toBe(true);
            expect(await ordinary).toEqual([{ Done: { in_reply_to: 3 } }]);
          } else if (event === "startedWithNotice" || event === "pageWithNotice") {
            const reply = event === "startedWithNotice" ? { kind: "started", token: token2 } : { kind: "page", page: { ...token2, terminal: true, bytes: [226, 156, 147] } };
            broadcast.push({ instanceId: 7, frames: [encodeAppFrame({ LocalInteractionQuery: { reply } }), encodeAppFrame({ Ephemeral: { presence: [], presence_generation: 0, transient_generation: 0, interaction: [] } }), encodeAppFrame({ UiPatch: { in_reply_to: null, surface: "fixture", kind: "graph", revision: 1, base_revision: 0, ops: [] } })] });
            await flush();
            expect(ordinaryComplete).toBe(false);
          } else if (event === "page")
            push({ kind: "page", page: { ...token2, terminal: true, bytes: [226, 156, 147] } });
          else if (event === "consume")
            consume();
          else if (event === "consumeError")
            await flush();
          else if (event === "ack" || event === "cancel") {
            await flush();
            const last = sent.at(-1);
            expect(last && "LocalInteractionQuery" in last ? last.LocalInteractionQuery.command : null).toEqual({ kind: event === "ack" ? "acknowledge" : "cancel", token: token2 });
          } else if (event === "closed") {
            expect(complete).toBe(false);
            push({ kind: "closed", token: token2, cancelled: row.cancelled });
          }
          await flush();
        }
        const result3 = await queryResult;
        expect(complete).toBe(true);
        if (!row.cancelled)
          expect(result3).toEqual(token2.identity);
        else
          expect(result3).toBeInstanceOf(Error);
        client.dispose();
      }
    });
